<?php
// Included only after the published trip has been loaded.
if(!isset($t) || !function_exists('h')){http_response_code(404);exit;}
$d=tripDetails($t['id']);
$lines=static fn($s)=>array_values(array_filter(array_map('trim',preg_split('/\R/',(string)$s)),static fn($v)=>$v!==''));
$days=$lines($t['itinerary']);
$contact='?page=contact&id='.(int)$t['id'];
$photos=array_values(array_unique(array_merge([tripImage($t)],array_filter($lines($d['gallery']??''),static fn($v)=>filter_var($v,FILTER_VALIDATE_URL)&&str_starts_with($v,'https://')))));
?>
<div class="journey-v2">
<a class="j-back" href="?page=trips">← Explore all journeys</a>
<div class="j-gallery"><?php foreach($photos as $i=>$photo):?><a href="<?=h($photo)?>" target="_blank" rel="noopener" <?= $i?'hidden':''?>><img src="<?=h($photo)?>" alt="<?=h($t['title'])?> — destination inspiration <?=$i+1?>"></a><?php endforeach;?><span class="j-photo-label">Destination inspiration</span><?php if(count($photos)>1):?><button type="button" data-gallery-next>Next photo →</button><?php endif;?></div>
<div class="j-heading"><span class="eyebrow">THE NEXT CHAPTER / GROUP JOURNEYS</span><h1><?=h($t['title'])?></h1><p><?=h($t['description'])?></p><div class="j-facts"><span>Departure & route<br><strong><?=h($t['route'])?></strong></span><span>Travel dates<br><strong><?=h($t['dates'])?></strong></span><span>Travel style<br><strong>Small group</strong></span></div></div>
<nav class="j-tabs" aria-label="Journey sections"><?php foreach(['itinerary'=>'Itinerary','details'=>'Details','included'=>'Inclusions','reviews'=>'Reviews','notices'=>'Notices'] as $key=>$label):?><a href="#j-<?=$key?>"><?=h($label)?></a><?php endforeach;?></nav>
<div class="j-layout"><div class="j-content">
<section id="j-itinerary"><div class="j-section-head"><h2>Your story unfolds</h2><button type="button" data-print>Print / save PDF</button></div><p class="j-muted">Proposed itinerary · subject to confirmation</p><?php foreach($days as $i=>$day): $parts=explode('|',$day,2);?><details class="j-day"><summary><span class="j-num"><?=sprintf('%02d',$i+1)?></span><strong><?=h(trim($parts[0]))?></strong><span class="j-plus">+</span></summary><p><?=h(trim($parts[1]??'Further scheduling details will be confirmed before departure.'))?></p></details><?php endforeach;?><div class="j-question"><strong>Curious about the pace of this journey?</strong><p>Ask about free time, accommodation or daily activities.</p><a href="<?=h($contact)?>">Talk to our team →</a></div></section>
<section id="j-details"><h2>About this journey</h2><p><?=nl2br(h($t['description']))?></p><h3>Meeting and return</h3><p><?=nl2br(h($d['meeting']??'Meeting point and return arrangements will be confirmed before departure.'))?></p><h3>Experiences</h3><?php foreach($lines($d['activities']??'') as $v):?><p>• <?=h($v)?></p><?php endforeach;?></section>
<section id="j-included"><h2>What is included</h2><?php foreach(['inclusions'=>'Included','exclusions'=>'Not included','optional_activities'=>'Optional experiences'] as $k=>$label):?><h3><?=h($label)?></h3><?php $items=$lines($k==='inclusions'?$t[$k]:($d[$k]??''));if(!$items):?><p class="j-muted">To be confirmed.</p><?php endif;?><ul class="j-checks"><?php foreach($items as $v):?><li><span aria-hidden="true"><?=$k==='inclusions'?'✓':($k==='exclusions'?'×':'+')?></span><?=h($v)?></li><?php endforeach;?></ul><?php endforeach;?></section>
<section id="j-reviews"><h2>Traveller stories</h2><p>No verified reviews yet.</p></section>
<section id="j-notices"><h2>Before you go</h2><?php foreach(['Booking and availability'=>'Enquiries do not confirm a reservation. Final availability and pricing must be confirmed.','Passports and visas'=>'Entry requirements depend on nationality and travel documents. Confirm requirements before departure.','Cancellation and refunds'=>'Written cancellation and refund terms will be provided before any booking commitment.','Travel insurance'=>'Consider suitable medical and cancellation coverage.','Itinerary changes'=>'Activities and timing may change due to weather, availability or operational requirements.'] as $label=>$body):?><details class="j-day"><summary><strong><?=h($label)?></strong><span class="j-plus">+</span></summary><p><?=h($body)?></p></details><?php endforeach;?><?php foreach($lines($d['notices']??'') as $v):?><p><?=h($v)?></p><?php endforeach;?></section>
<section><h2>More journeys</h2><?php foreach(q('SELECT * FROM trips WHERE published=1 AND id<>? ORDER BY id DESC LIMIT 4',[$t['id']]) as $other):?><a class="j-related" href="?page=trip&id=<?=(int)$other['id']?>"><img loading="lazy" src="<?=h(tripImage($other))?>" alt=""><span><strong><?=h($other['title'])?></strong><br><?=h($other['dates'])?></span><span>→</span></a><?php endforeach;?></section>
</div><aside class="j-book"><span class="eyebrow">YOUR NEXT BOARDING</span><h2>Make it your story.</h2><p>Personalized pricing on request.</p><a class="j-primary" href="<?=h($contact)?>">Register interest →</a><a class="j-secondary" href="<?=h($contact)?>">Ask about trip</a><small>No payment or commitment required.</small><button type="button" data-share>Share journey</button></aside></div></div>
